        BlockPos enginePos = util.grid().at(1, 2, 2);
        Selection engine = util.select().position(enginePos);
        Selection pump = util.select().position(pumpPos);
        Selection pipe = util.select().fromTo(1, 1, 2, 4, 1, 2);
        Selection pumpShaft = util.select().fromTo(3, 1, 3, 5, 1, 3);
        Selection shaft = util.select().fromTo(1, 2, 0, 1, 2, 4);
        Selection cog = util.select().position(5, 0, 4);
        Selection lever = util.select().fromTo(0, 1, 2, 0, 2, 2);
        scene.idle(15);
        ElementLink engineElement = scene.world().showIndependentSection(engine, Direction.DOWN);
        scene.world().moveSection(engineElement, util.vector().of(0.0, -1.0, 0.0), 0);
        scene.idle(15);
        scene.overlay().showText(70).attachKeyFrame().text("Diesel Engines are a compact way of generating kinetic energy.").pointAt(util.vector().blockSurface(util.grid().at(1, 1, 2), Direction.NORTH)).placeNearTarget();
