        Selection distillationTank = util.select().fromTo(3, 2, 2, 4, 4, 3);
        Selection windowedTank = util.select().fromTo(3, 2, 4, 4, 4, 5);
        Selection tank = util.select().fromTo(3, 2, 0, 4, 4, 1);
