        scene.world().showSection(tank, Direction.NORTH);
        scene.idle(20);
        scene.world().showSection(largeCog, Direction.DOWN);
        scene.world().showSection(cogShafts, Direction.DOWN);
        scene.world().showSection(cog, Direction.DOWN);
        scene.idle(20);
