        scene.world().setKineticSpeed(largeCog, 16.0f);
        scene.world().setKineticSpeed(cogShafts, -32.0f);
        scene.world().setKineticSpeed(pump, 32.0f);
        scene.world().setKineticSpeed(cog, 32.0f);
        scene.world().setKineticSpeed(turret, -32.0f);
        scene.overlay().showText(70).attachKeyFrame().text("They need to be supplied with a fluid, and powered by a cogwheel.").pointAt(util.vector().blockSurface(util.grid().at(2, 2, 2), Direction.NORTH)).placeNearTarget();
        scene.idle(80);
        scene.rotateCameraY(-90.0f);
        scene.idle(20);
        scene.world().showSection(redstoneControl, Direction.DOWN);

