        CompressionMoldingRecipe compressionMoldingRecipe = (CompressionMoldingRecipe)recipe;
        ItemStack stack = CDGItems.MOLD.asStack();
        stack.m_41700_("Mold", (Tag)StringTag.m_129297_((String)compressionMoldingRecipe.moldType.getId().toString()));
        builder.addSlot(RecipeIngredientRole.CATALYST, 36, 11).setBackground(CompressionMoldingCategory.getRenderedSlot(), -1, -1).addItemStack(stack);
    }

    public void draw(BasinRecipe recipe, IRecipeSlotsView iRecipeSlotsView, GuiGraphics graphics, double mouseX, double mouseY) {
        super.draw(recipe, iRecipeSlotsView, graphics, mouseX, mouseY);
